CREATE DATABASE IF NOT EXISTS society_maintenance CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE society_maintenance;
CREATE TABLE residents(resident_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(20),password VARCHAR(255) NOT NULL,building VARCHAR(20) NOT NULL,flat_no VARCHAR(20) NOT NULL,registered_on TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admins(admin_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE staff(staff_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(20),specialization VARCHAR(100) NOT NULL,status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE complaints(complaint_id INT AUTO_INCREMENT PRIMARY KEY,resident_id INT NOT NULL,staff_id INT NULL,category VARCHAR(50) NOT NULL,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,location VARCHAR(150) NOT NULL,priority ENUM('Low','Medium','High') DEFAULT 'Medium',image_path VARCHAR(255),status ENUM('Submitted','Assigned','In Progress','Resolved') DEFAULT 'Submitted',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(resident_id) REFERENCES residents(resident_id) ON DELETE CASCADE,FOREIGN KEY(staff_id) REFERENCES staff(staff_id) ON DELETE SET NULL);
CREATE TABLE status_history(history_id INT AUTO_INCREMENT PRIMARY KEY,complaint_id INT NOT NULL,status ENUM('Submitted','Assigned','In Progress','Resolved') NOT NULL,remarks VARCHAR(255),updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(complaint_id) ON DELETE CASCADE);
CREATE TABLE feedback(feedback_id INT AUTO_INCREMENT PRIMARY KEY,complaint_id INT NOT NULL UNIQUE,resident_id INT NOT NULL,rating TINYINT NOT NULL,comments TEXT,feedback_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(complaint_id) ON DELETE CASCADE,FOREIGN KEY(resident_id) REFERENCES residents(resident_id) ON DELETE CASCADE);
